  "schemeId": "MS-mspi",
  "name": "Merit Scholarship: Polytechnic Institutions",
  "shortTitle": "MSPI",
  "category": "Student / Education",
  "level": "State",
  "state": "Chhattisgarh",
  "ministryOrDepartment": "Technical Education Department, Government of Chhattisgarh",
  "description": "\"Merit Scholarship: Polytechnic Institutions\" is a scholarship scheme by the Technical Education Department, Government of Chhattisgarh. The scheme provides ₹600/- per month to eligible students for pursuing education from recognized polytechnic institutions in Chhattisgarh.",
  "summaryText": "\"Merit Scholarship: Polytechnic Institutions\" is a scholarship scheme by the Technical Education Department, Government of Chhattisgarh.",
  "financialBenefit": "Students enrolled in recognized polytechnic institutions receive a monthly scholarship of 600 rupees.",
  "financialBenefitAmount": 600,
  "eligibilityRules": {
   "statesAllowed": [
    "Chhattisgarh"
   ],
   "educationAllowed": [
    "10th",
    "12th"
   ],
   "otherConditions": [
    "Must be currently studying in a recognized polytechnic institution in Chhattisgarh",
    "Must not be in full-time employment"
   ],
   "occupationsAllowed": [
    "Student"
   ]
  },
  "documentsRequired": [
   "Residential Certificate of Chhattisgarh.",
   "Mark sheet of the Qualifying Examination."
  ],
